  "Hedef klasörler uygun": {"tr":"Hedef klasörler uygun","en":"The target folders are suitable"},
  "Yeterli disk alanı var": {"tr":"Yeterli disk alanı var","en":"There is enough disk space"},
  "Yedek türü destekleniyor": {"tr":"Yedek türü destekleniyor","en":"The backup type is supported"},
  "Sunucu sürümleri uyumlu": {"tr":"Sunucu sürümleri uyumlu","en":"The server versions are compatible"},
  "Sunucu sürüm türü uyumlu": {"tr":"Sunucu sürüm türü uyumlu","en":"The server edition is compatible"},
  "Hedef, yedeğin kaynağıyla uyumlu": {"tr":"Hedef, yedeğin kaynağıyla uyumlu","en":"The target matches the backup's source"},
  "Dosya türleri destekleniyor": {"tr":"Dosya türleri destekleniyor","en":"The file types are supported"},
  "Dosya yerleşimi hazır": {"tr":"Dosya yerleşimi hazır","en":"The file layout is ready"},
  "Geçici klasöre yazılabiliyor": {"tr":"Geçici klasöre yazılabiliyor","en":"The temporary folder is writable"},
  "Geçici klasörde yeterli alan var": {"tr":"Geçici klasörde yeterli alan var","en":"There is enough space in the temporary folder"},
  "Geçici klasör yolu geçerli": {"tr":"Geçici klasör yolu geçerli","en":"The temporary folder path is valid"},
  "Sunucu geçici klasöre yazabiliyor": {"tr":"Sunucu geçici klasöre yazabiliyor","en":"The server can write to the temporary folder"},
  "Geçici klasör sunucuyla paylaşılıyor": {"tr":"Geçici klasör sunucuyla paylaşılıyor","en":"The temporary folder is shared with the server"},
  "Diğer kontrol": {"tr":"Diğer kontrol","en":"Other check"},
  "Neden soruluyor?": {"tr":"Neden soruluyor?","en":"Why are we asking?"},
  "Adsız bilgisayar": {"tr":"Adsız bilgisayar","en":"Unnamed computer"},
  "Bilgisayar bulunamadı": {"tr":"Bilgisayar bulunamadı","en":"Computer not found"},
  "Bilgisayar iptal edildi": {"tr":"Bilgisayar iptal edildi","en":"Computer revoked"},
  "Bu bilgisayar iptal edildi; yeni bir yedekleme işi oluşturun.": {"tr":"Bu bilgisayar iptal edildi; yeni bir yedekleme işi oluşturun.","en":"This computer was revoked; create a new backup job."},
  "Bilgisayarı iptal edilmiş işler": {"tr":"Bilgisayarı iptal edilmiş işler","en":"Jobs of revoked computers"},
  "Değiştir: {0}": {"tr":"Değiştir: {0}","en":"Change: {0}"},
  "Her şey doğru mu?": {"tr":"Her şey doğru mu?","en":"Is everything correct?"},
  "Kaydet'e basmadan önce neyin oluşturulacağını son kez görürsünüz; hiçbir şey o ana kadar değişmez.": {"tr":"Kaydet'e basmadan önce neyin oluşturulacağını son kez görürsünüz; hiçbir şey o ana kadar değişmez.","en":"You see what will be created one last time before pressing Save; nothing changes until then."},
  "{0} (devre dışı)": {"tr":"{0} (devre dışı)","en":"{0} (disabled)"},
  "Özel zamanlama": {"tr":"Özel zamanlama","en":"Custom schedule"},
  "Elle çalıştırılır (zamanlama yok)": {"tr":"Elle çalıştırılır (zamanlama yok)","en":"Runs manually (no schedule)"},
  "{0} gün": {"tr":"{0} gün","en":"{0} days"},
  "Bir yedekleme bilgisayarı seçin.": {"tr":"Bir yedekleme bilgisayarı seçin.","en":"Select a backup computer."},
  "Yedekleme bilgisayarı seçin": {"tr":"Yedekleme bilgisayarı seçin","en":"Select a backup computer"},
  "Bilgisayar listesi yükleniyor…": {"tr":"Bilgisayar listesi yükleniyor…","en":"Loading computers…"},
  "Yedekler şifrelensin mi?": {"tr":"Yedekler şifrelensin mi?","en":"Should backups be encrypted?"},
  "Şifreli bir yedek, dosya yanlış ellere geçse bile okunamaz.": {"tr":"Şifreli bir yedek, dosya yanlış ellere geçse bile okunamaz.","en":"An encrypted backup cannot be read even if the file falls into the wrong hands."},
  "Yedekler ne kadar süre saklansın?": {"tr":"Yedekler ne kadar süre saklansın?","en":"How long should backups be kept?"},
  "Süresi dolan yedekler silinir; böylece depolama alanı gereksiz yere dolmaz.": {"tr":"Süresi dolan yedekler silinir; böylece depolama alanı gereksiz yere dolmaz.","en":"Expired backups are deleted so that storage space does not fill up needlessly."},
  "Saklama süresi": {"tr":"Saklama süresi","en":"Retention period"},
  "Yedek ne zaman alınsın?": {"tr":"Yedek ne zaman alınsın?","en":"When should the backup run?"},
  "Düzenli yedek, bir sorun çıktığında kaybedeceğiniz veriyi sınırlar. Elle çalıştırma her zaman mümkündür.": {"tr":"Düzenli yedek, bir sorun çıktığında kaybedeceğiniz veriyi sınırlar. Elle başlatma her zaman mümkündür.","en":"Regular backups limit how much data you lose when something goes wrong. Running a backup manually is always possible."},
  "Elle çalıştır": {"tr":"Elle çalıştır","en":"Run manually"},
  "Kaydedilmiş zamanlamanın sonraki çalışması: {0}. Değişiklikler kaydedildikten sonra sunucu tarafından hesaplanır.": {"tr":"Kaydedilmiş zamanlamanın sonraki çalışması: {0}. Değişiklikler kaydedildikten sonra sunucu tarafından hesaplanır.","en":"Next scheduled attempt: {0}. Changes are calculated by the server after saving."},
  "Kaynak türü": {"tr":"Kaynak türü","en":"Source type"},
  "Hangi dosya ve klasörleri yedekleyeceğiz?": {"tr":"Hangi dosya ve klasörleri yedekleyeceğiz?","en":"Which files and folders should we back up?"},
  "Hangi veritabanını yedekleyeceğiz?": {"tr":"Hangi veritabanını yedekleyeceğiz?","en":"Which database should we back up?"},
  "Yedeğin neyi kapsayacağını ve oraya nasıl ulaşılacağını bilmemiz gerekir.": {"tr":"Yedeğin neyi kapsayacağını ve oraya nasıl ulaşılacağını bilmemiz gerekir.","en":"We need to know what the backup covers and how to reach it."},
  "Yedek nereye yazılsın?": {"tr":"Yedek nereye yazılsın?","en":"Where should the backup be written?"},
  "Yedeğin güvenle saklanacağı yeri seçmeniz gerekir; seçmezseniz varsayılan depolama kullanılır.": {"tr":"Yedeğin güvenle saklanacağı yeri seçmeniz gerekir; seçmezseniz varsayılan depolama kullanılır.","en":"Choose where the backup is stored safely; if you do not choose, the default storage is used."},
  "Bilgisayar": {"tr":"Bilgisayar","en":"Computer"},
  "Her gün 02:00": {"tr":"Her gün 02:00","en":"Every day at 02:00"},
  "Her gün 08:00": {"tr":"Her gün 08:00","en":"Every day at 08:00"},
  "İş ayrıntıları": {"tr":"İş ayrıntıları","en":"Job details"},
  "Yedekleme bilgisayarı bulunamadı": {"tr":"Yedekleme bilgisayarı bulunamadı","en":"Backup computer not found"},
  "Son sonuç": {"tr":"Son sonuç","en":"Last result"},
  "Başka bir yedekleme denemesi sürdüğü için yenisi başlatılmadı.": {"tr":"Başka bir yedekleme denemesi sürdüğü için yenisi başlatılmadı.","en":"A new backup attempt was not started because another one is still in progress."},
  "Zaten sürüyor": {"tr":"Zaten sürüyor","en":"Already running"},
  "Süren denemeyi aç": {"tr":"Süren denemeyi aç","en":"Open the running attempt"},
