  "Hiç silinmesin": {"tr":"Hiç silinmesin","en":"Never delete"},
  "{0} hedeften en az {1} tanesi doğrulanmalıdır.": {"tr":"{0} hedeften en az {1} tanesi doğrulanmalıdır.","en":"At least {1} of {0} destinations must be verified."},
  "Özet ve onay": {"tr":"Özet ve onay","en":"Review and confirm"},
  "Yedekleme işi ve bilgisayar": {"tr":"Yedekleme işi ve bilgisayar","en":"Backup job and computer"},
  "İşi listelerde bu adla tanırsınız; yedeği, kaynağa ulaşabilen yedekleme bilgisayarındaki program alır.": {"tr":"İşi listelerde bu adla tanırsınız; yedeği, kaynağa ulaşabilen yedekleme bilgisayarındaki program alır.","en":"You will recognise the job by this name in lists; the program on the backup computer that can reach the source takes the backup."},
  "Kaydedilmemiş değişiklikler atılsın mı?": {"tr":"Kaydedilmemiş değişiklikler atılsın mı?","en":"Discard unsaved changes?"},
  "Bu formda girdiğiniz değerler kaydedilmeden kapatılır.": {"tr":"Bu formda girdiğiniz değerler kaydedilmeden kapatılır.","en":"The values you entered in this form are closed without being saved."},
  "Yalnızca bu formu etkiler; kayıtlı işler ve yedekler değişmez.": {"tr":"Yalnızca bu formu etkiler; kayıtlı işler ve yedekler değişmez.","en":"Only this form is affected; saved jobs and backups do not change."},
  "Hayır, değerleri yeniden girmeniz gerekir.": {"tr":"Hayır, değerleri yeniden girmeniz gerekir.","en":"No, you would have to enter the values again."},
  "Değişiklikleri at": {"tr":"Değişiklikleri at","en":"Discard changes"},
  "Hedef depolama bağlantısı doğrulanamadı veya kullanılamıyor. Depolama bölümünde hedefi düzeltin.": {"tr":"Hedef depolama bağlantısı doğrulanamadı veya kullanılamıyor. Depolama bölümünde hedefi düzeltin.","en":"The destination storage connection could not be verified or is unavailable. Fix the destination in the Storage section."},
  "Kaynak, depolama, zamanlama ve koruma ayarlarını adım adım belirleyin.": {"tr":"Kaynak, depolama, zamanlama ve koruma ayarlarını adım adım belirleyin.","en":"Set the source, storage, schedule and protection step by step."},
  "Yedekleri alacak bilgisayara küçük bir program kurulur.": {"tr":"Yedekleri alacak bilgisayara küçük bir program kurulur.","en":"A small program is installed on the computer that will take the backups."},
  "Çevrimiçi. Kurulum tamamlandı.": {"tr":"Çevrimiçi. Kurulum tamamlandı.","en":"Online. Setup is complete."},
  "Veritabanlarını listelemek için giriş bilgilerini girin.": {"tr":"Veritabanlarını listelemek için giriş bilgilerini girin.","en":"Enter the login details to list the databases."},
  "Giriş bilgilerini kontrol edip yeniden kaydedin.": {"tr":"Giriş bilgilerini kontrol edip yeniden kaydedin.","en":"Check the login details and save again."},
  "Uyarılar": {"tr":"Uyarılar","en":"Warnings"},
